package com.fooddelivery.user.service; import java.util.*;import org.springframework.stereotype.Service;import com.fooddelivery.user.entity.User;import com.fooddelivery.user.dto.UserDto;import com.fooddelivery.user.mapper.UserMapper;import com.fooddelivery.user.repository.UserRepository;@Service public class UserService{private final UserRepository repo;private final UserMapper mapper;public UserService(UserRepository r,UserMapper m){repo=r;mapper=m;}public UserDto create(UserDto d){return mapper.toDto(repo.save(mapper.toEntity(d)));}public List<UserDto> all(){List<UserDto> x=new ArrayList<>();for(User u:repo.findAll())x.add(mapper.toDto(u));return x;}public UserDto get(Long id){return mapper.toDto(repo.findById(id).orElseThrow(()->new NoSuchElementException("User not found")));}}
